/** Pure shared contract: no database, process, filesystem, Bun or emissions arithmetic. */
import {m71CanonicalJson,m71Keys,m71Uuid,m71HashString,M71_EVIDENCE_SHA256} from './m71-validation'
import {M71_ARTIFACT,type M71Version} from './m71-contract'
import {M73_PROFILE,M73_PERIOD,M73_LIMITATIONS,type M73SaveInput,type M73ReviewInput,type M73ReportInput,type M73Activity,type M73Version,type M73Review,type M73Report,type M73Calculation,type M73Finding,type M73SourceChoice,type M73BindingInput} from './m73-contract'
export const m73CanonicalJson=m71CanonicalJson
export class M73ValidationError extends Error {}
export const m73Require=(v:unknown,message='Invalid synthetic natural-gas request.'):void=>{if(!v)throw new M73ValidationError(message)}
export const m73Keys=(v:unknown,keys:string[])=>{try{m71Keys(v,keys)}catch{throw new M73ValidationError('Unexpected or missing natural-gas fields.')}}
export function m73Text(v:unknown,max=500):string{m73Require(typeof v==='string'&&v.length>0);const s=(v as string).trim().normalize('NFC');m73Require(s.length>0&&Array.from(s).length<=max&&!/[\u0000-\u001f\u007f-\u009f\ud800-\udfff]/u.test(s));return s}
export const m73NullableText=(v:unknown,max=500)=>v===null?null:m73Text(v,max)
export function m73Quantity(v:unknown):string{m73Require(typeof v==='string'&&/^(?:0|[1-9][0-9]{0,11})(?:\.[0-9]{1,3})?$/.test(v));const [a,b='']=(v as string).split('.');return a+'.'+b.padEnd(3,'0')}
export function validateM73Save(value:unknown):M73SaveInput{
 m73Keys(value,['profile','binding','period','fuel','heatBasis','unit','quantityMmbtu','statement','manualConfirmation','discrepancyReason','zeroReason','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey'])
 const v=structuredClone(value) as M73SaveInput
 m73Keys(v.binding,['coverageVersionId','coverageVersionSha256','entityId','facilityId','sourceId','boundaryDecisionId']);for(const [k,x]of Object.entries(v.binding))m73Require(k.endsWith('Sha256')?m71HashString(x):m71Uuid(x))
 m73Keys(v.period,['start','endExclusive']);m73Require(v.profile===M73_PROFILE&&m73CanonicalJson(v.period)===m73CanonicalJson(M73_PERIOD)&&v.fuel==='Natural Gas'&&v.heatBasis==='HHV'&&v.unit==='MMBtu'&&typeof v.manualConfirmation==='boolean'&&m71Uuid(v.idempotencyKey))
 v.quantityMmbtu=v.quantityMmbtu===null?null:m73Quantity(v.quantityMmbtu)
 if(v.statement!==null){m73Keys(v.statement,['issuer','reference','meterLabel','statedQuantityMmbtu','description','consumptionBasis']);m73Require(v.statement.consumptionBasis==='dedicated_meter_consumed_no_adjustments');v.statement={...v.statement,issuer:m73Text(v.statement.issuer,120),reference:m73Text(v.statement.reference,120),meterLabel:m73Text(v.statement.meterLabel,120),statedQuantityMmbtu:m73Quantity(v.statement.statedQuantityMmbtu),description:m73Text(v.statement.description,2000)}}
 v.discrepancyReason=m73NullableText(v.discrepancyReason);v.zeroReason=m73NullableText(v.zeroReason);v.correctionReason=m73NullableText(v.correctionReason)
 if(v.expectedVersionId===null)m73Require(v.expectedVersionSha256===null&&v.correctionReason===null);else m73Require(m71Uuid(v.expectedVersionId)&&m71HashString(v.expectedVersionSha256)&&v.correctionReason!==null)
 if(v.quantityMmbtu!==null){m73Require(v.statement!==null&&v.manualConfirmation,'A numeric calculation needs a retained statement and manual confirmation.');if(v.quantityMmbtu==='0.000')m73Require(v.statement!.statedQuantityMmbtu==='0.000'&&v.zeroReason!==null,'Zero needs a zero-supporting statement and no-consumption reason.');else if(v.quantityMmbtu!==v.statement!.statedQuantityMmbtu)m73Require(v.discrepancyReason!==null,'Explain the unresolved entered-versus-stated discrepancy.')}
 return v
}
export function validateM73Review(value:unknown):M73ReviewInput{m73Keys(value,['versionId','expectedVersionSha256','decision','note','acknowledgedLimitations','idempotencyKey']);const v=structuredClone(value) as M73ReviewInput;m73Require(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71Uuid(v.idempotencyKey)&&['accepted_bounded_internal','changes_requested'].includes(v.decision)&&m73CanonicalJson(v.acknowledgedLimitations)===m73CanonicalJson(M73_LIMITATIONS));v.note=m73Text(v.note);return v}
export function validateM73Report(value:unknown):M73ReportInput{m73Keys(value,['versionId','expectedVersionSha256','expectedDecisionId','expectedDecisionSha256','idempotencyKey']);const v=value as M73ReportInput;m73Require(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71Uuid(v.idempotencyKey)&&(v.expectedDecisionId===null?v.expectedDecisionSha256===null:m71Uuid(v.expectedDecisionId)&&m71HashString(v.expectedDecisionSha256)));return structuredClone(v)}
export function m73Activity(v:M73SaveInput):M73Activity{const {expectedVersionId:_,expectedVersionSha256:__,correctionReason:___,idempotencyKey:____,...activity}=v;return activity}
export function deriveM73Findings(a:M73Activity):M73Finding[]{const findings=[{code:'scope1_incomplete',message:'This source subtotal does not cover all stationary, mobile, fugitive or process emissions.'},{code:'method_not_released',message:'Factors and method are development candidates; no reporting or assurance determination.'}];if(a.quantityMmbtu===null)findings.push({code:'activity_missing',message:'Activity is missing; no emissions were calculated.'});if(a.statement===null)findings.push({code:'statement_missing',message:'No synthetic activity statement is retained.'});if(a.quantityMmbtu!==null&&a.statement&&a.quantityMmbtu!==a.statement.statedQuantityMmbtu)findings.push({code:'activity_statement_discrepancy',message:'Entered and stated quantities differ; the discrepancy remains unresolved.'});return findings}
export function m73SourceChoices(v:M71Version):M73SourceChoice[]{const s=v.snapshot,within=(x:{start:string;endExclusive:string})=>x.start===M73_PERIOD.start&&x.endExclusive===M73_PERIOD.endExclusive;return s.sources.filter(x=>x.domain==='stationary_combustion').map(source=>{const e=s.entities.find(x=>x.id===source.entityId),f=s.facilities.find(x=>x.id===source.facilityId),b=s.boundaryDecisions.find(x=>x.entityId===source.entityId&&within(x));const findings:M73Finding[]=[];const add=(message:string)=>findings.push({code:'source_ineligible',message});if(s.consolidationApproach!=='operational_control'||!within(s.period)||!e||!f||f.entityId!==e.id||e.countryCode!=='US'||e.regionCode!=='CA'||f.countryCode!=='US'||f.regionCode!=='CA'||!within(e)||!within(f)||!within(source))add('Selected source needs a full-year2025 California operational-control entity and facility.');const supportedRefs=(refs:{artifactId:string;expectedSha256:string;locator:string}[])=>refs.some(r=>r.artifactId===M71_ARTIFACT.id&&r.expectedSha256===M71_EVIDENCE_SHA256&&r.locator===M71_ARTIFACT.locator);if(!b||b.disposition!=='included_activity'||!b.reason?.trim()||!supportedRefs(b.evidenceRefs))add('Save the entity inclusion rationale and pinned fictional boundary reference first.');let id=e?.id;const seen=new Set<string>();while(id){if(seen.has(id)){add('Boundary relationship cycle.');break}seen.add(id);const rel=s.relationships.find(r=>r.childEntityId===id);if(!rel)break;if(!within(rel)||rel.ownershipPercent!=='100'||!rel.controlFacts?.trim()||!supportedRefs(rel.evidenceRefs))add('Every selected relationship requires full-year operational-control facts and fictional support.');id=rel.parentEntityId}return {binding:{coverageVersionId:v.id,coverageVersionSha256:v.versionSha256,entityId:source.entityId,facilityId:source.facilityId??'',sourceId:source.id,boundaryDecisionId:b?.id??''},companyLabel:s.companyLabel,entityLabel:e?.legalName??'',facilityLabel:f?.name??'',sourceLabel:source.name,eligible:findings.length===0,findings}})}
export function m73ResolveBinding(binding:M73BindingInput,coverage:M71Version){const choice=m73SourceChoices(coverage).find(s=>s.binding.sourceId===binding.sourceId);m73Require(choice?.eligible&&m73CanonicalJson(choice.binding)===m73CanonicalJson(binding),'The selected saved source or boundary is not eligible.');return choice!}
export function m73StatementText(a:M73Activity,v:M71Version):string{m73Require(a.statement!==null);const c=m73ResolveBinding(a.binding,v);return 'SYNTHETIC — NOT A UTILITY BILL\n'+m73CanonicalJson({profile:'m73-synthetic-gas-statement-v1',companyLabel:c.companyLabel,entityLabel:c.entityLabel,facilityLabel:c.facilityLabel,sourceLabel:c.sourceLabel,binding:a.binding,period:a.period,fuel:a.fuel,heatBasis:a.heatBasis,unit:a.unit,statement:a.statement})+'\n'}
export const m73InputHashPayload=(v:Pick<M73Version,'activity'>)=>v.activity
export const m73ContentPayload=(v:Pick<M73Version,'activity'|'coverageVersion'|'statement'|'calculation'|'findings'>)=>({activity:v.activity,coverageVersion:v.coverageVersion,statement:v.statement,calculation:v.calculation,findings:v.findings})
export const m73VersionHashPayload=(v:M73Version)=>({profile:M73_PROFILE,id:v.id,companyId:v.companyId,worksheetId:v.worksheetId,version:v.version,previousVersionId:v.previousVersionId,previousVersionSha256:v.previousVersionSha256,createdBy:v.createdBy,createdAt:v.createdAt,contributorIds:v.contributorIds,correctionReason:v.correctionReason,inputSha256:v.inputSha256,contentSha256:v.contentSha256})
export function m73ReviewHashPayload(companyId:string,r:M73Review){const {decisionSha256:_,...body}=r;return {profile:M73_PROFILE,companyId,...body}}
export function m73ReportHashPayload(r:M73Report){const {reportSha256:_,html:__,snapshotJson:___,...body}=r;return {profile:M73_PROFILE,...body}}
export function m73CalculationHashPayload(c:M73Calculation){const {resultSha256:_,...body}=c;return body}
export const m73Export=(v:M73Version)=>m73CanonicalJson({...v,review:null})

export const M73_REPORT_TEMPLATE=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Synthetic stationary natural-gas source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Stationary natural-gas source report — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source and activity</h2><dl>{{facts}}</dl><h2>Gas results and calculation trace</h2>{{calculation}}<h2>Supporting synthetic statement</h2><dl>{{statement}}</dl><h2>Corporate coverage remains incomplete</h2><p>Stationary combustion is partial. Mobile combustion, fugitive emissions including refrigerants, process emissions, other sources/facilities/periods, Scope 2 and all 15 Scope 3 categories remain unresolved or separately assessed. Combustion only; upstream fuel emissions excluded.</p><ul>{{findings}}</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>{{snapshot}}</pre></details></body></html>`
import type {M73Version,M73Review} from './m73-contract'
import {m73CanonicalJson} from './m73-validation'
export const m73ReportSnapshot=(version:M73Version,review:M73Review|null)=>({profile:'m73-source-report-v1',version:{...version,review:null},review})
export function m73RenderReport(snapshot:ReturnType<typeof m73ReportSnapshot>):string{
 const v=snapshot.version,c=v.calculation,choice=v.coverageVersion.snapshot.sources.find(s=>s.id===v.activity.binding.sourceId),facility=v.coverageVersion.snapshot.facilities.find(f=>f.id===v.activity.binding.facilityId),entity=v.coverageVersion.snapshot.entities.find(e=>e.id===v.activity.binding.entityId),boundary=v.coverageVersion.snapshot.boundaryDecisions.find(b=>b.id===v.activity.binding.boundaryDecisionId)
 const esc=(value:unknown)=>String(value??'Missing').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')
 const pair=(label:string,value:unknown)=>'<dt>'+label+'</dt><dd>'+esc(value)+'</dd>'
 const fields:Record<string,string>={facts:pair('Company',v.coverageVersion.snapshot.companyLabel)+pair('Entity',entity?.legalName)+pair('Boundary basis',boundary?.reason)+pair('Facility',facility?.name)+pair('Source',choice?.name)+pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')+pair('Coverage version',v.activity.binding.coverageVersionId)+pair('Source version',v.version)+pair('Entered natural gas (MMBtu HHV)',v.activity.quantityMmbtu)+pair('Statement amount (MMBtu HHV)',v.activity.statement?.statedQuantityMmbtu)+pair('Discrepancy explanation',v.activity.discrepancyReason??'Not applicable')+pair('No-consumption explanation',v.activity.zeroReason??'Not applicable')+pair('Exact source subtotal (kg CO2e)',c?.total.unrounded)+pair('Displayed source subtotal (kg CO2e)',c?.total.display)+pair('Review as captured',snapshot.review?.decision??'Unreviewed')+pair('Reviewer note',snapshot.review?.note??'Not yet reviewed')+pair('Review time',snapshot.review?.reviewedAt??'Not yet reviewed')+pair('Correction reason',v.correctionReason??'Not applicable'),calculation:c?'<table><thead><tr><th>Gas</th><th>Mass (kg)</th><th>kg CO2e</th></tr></thead><tbody>'+(['co2','ch4','n2o'] as const).map((key,index)=>'<tr><th>'+['CO2','CH4','N2O'][index]+'</th><td>'+esc(c.gasResults[key].mass)+'</td><td>'+esc(c.gasResults[key].co2e)+'</td></tr>').join('')+'</tbody></table><p>Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>':'<p>Activity is missing; no emissions total was calculated.</p>',statement:v.statement?pair('Statement type','Synthetic — not a utility bill')+pair('Issuer',v.activity.statement?.issuer)+pair('Reference',v.activity.statement?.reference)+pair('Dedicated meter',v.activity.statement?.meterLabel)+pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')+pair('Stated energy (MMBtu HHV)',v.activity.statement?.statedQuantityMmbtu)+pair('Description',v.activity.statement?.description)+pair('Retained statement locator',v.statement.locator)+pair('Statement SHA-256',v.statement.sha256):pair('Evidence','No supporting statement entered'),findings:[...new Set([...v.findings,...v.coverageVersion.findings].map(f=>f.message))].map(message=>'<li>'+esc(message)+'</li>').join(''),snapshot:esc(m73CanonicalJson(snapshot))}
 return M73_REPORT_TEMPLATE.replace(/\{\{(facts|calculation|statement|findings|snapshot)\}\}/g,(_,key:string)=>fields[key]!)
}

import type {WorkspaceSql} from './workspace'
import {readCorporateInventory,m71Export} from './m71'
import {M73_PROFILE,M73_LIMITATIONS,M73_METHOD,type M73Authority,type M73Register,type M73Version,type M73Review,type M73Report,type M73SaveInput,type M73ReviewInput,type M73ReportInput,type M73Calculation} from './m73-contract'
import {m73CanonicalJson,validateM73Save,validateM73Review,validateM73Report,m73Activity,m73ResolveBinding,m73SourceChoices,m73StatementText,m73InputHashPayload,m73ContentPayload,m73VersionHashPayload,m73ReviewHashPayload,m73ReportHashPayload,m73CalculationHashPayload,m73Export,deriveM73Findings,m73Keys} from './m73-validation'
import {m73RenderReport,m73ReportSnapshot} from './m73-report'
import {m71Uuid} from './m71-validation'
export * from './m73-contract'
export * from './m73-validation'
export * from './m73-report'
export const m73Hash=(v:unknown)=>new Bun.CryptoHasher('sha256').update(m73CanonicalJson(v)).digest('hex')
export const m73BytesHash=(s:string)=>new Bun.CryptoHasher('sha256').update(s).digest('hex')
const bytes=(s:string)=>new TextEncoder().encode(s).length
const same=(a:unknown,b:unknown)=>m73CanonicalJson(a)===m73CanonicalJson(b)
const flags={synthetic:true as const,scope1Completeness:'incomplete' as const,corporateCompleteness:'incomplete' as const,releaseEligible:false as const,assurance:'none' as const}
const fail=():never=>{throw Error('Stored natural-gas workpaper could not be verified.')}
const verify=(v:unknown)=>{if(!v)fail()}
const iso=(v:string)=>{const d=new Date(v);return Number.isFinite(d.getTime())?d.toISOString():fail()}
type RequestRow={company_id:string;idempotency_key:string;actor_id:string;kind:string;fingerprint:string;record_id:string}
type AuditRow={company_id:string;record_id:string;kind:string;record_sha256:string;actor_id:string;created_at:string}
export async function readStationaryGas(tx:WorkspaceSql,companyId:string,authority:M73Authority):Promise<M73Register|null>{
 if(!(await tx.query<{allowed:boolean}>('select neuvetra.m73_lock($1,false) allowed',[companyId])).rows[0]?.allowed)return null
 const coverage=await readCorporateInventory(tx,companyId);if(!coverage)return null
 const data=(await tx.query<{heads:any[];versions:any[];statements:any[];reviews:any[];reports:any[];requests:RequestRow[];audits:AuditRow[]}>(`select
 coalesce((select jsonb_agg(x order by id) from neuvetra.stationary_gas_heads x where company_id=$1),'[]') heads,
 coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('quantity_mmbtu',x.quantity_mmbtu::text) order by worksheet_id,version) from neuvetra.stationary_gas_versions x where company_id=$1),'[]') versions,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_gas_statements x where company_id=$1),'[]') statements,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_gas_reviews x where company_id=$1),'[]') reviews,
 coalesce((select jsonb_agg(x order by created_at,id) from neuvetra.stationary_gas_reports x where company_id=$1),'[]') reports,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_gas_requests x where company_id=$1),'[]') requests,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_gas_audit x where company_id=$1),'[]') audits`,[companyId])).rows[0]!
 verify(data.heads.length<=3&&data.versions.length<=40&&data.audits.length===data.versions.length+data.reviews.length+data.reports.length&&data.requests.length===data.audits.length)
 const audit=(kind:string,id:string,hash:string,actor:string,time:string,worksheetId:string|null,request:unknown)=>{const rows=data.audits.filter(a=>a.kind===kind&&a.record_id===id),req=data.requests.filter(r=>r.kind===kind&&r.record_id===id);verify(rows.length===1&&req.length===1);const a=rows[0]!,r=req[0]!;verify(a.company_id===companyId&&a.actor_id===actor&&a.record_sha256===hash&&iso(a.created_at)===time&&r.company_id===companyId&&r.actor_id===actor&&m71Uuid(r.idempotency_key)&&r.fingerprint===m73Hash({operation:kind,actor,companyId,worksheetId,request}))}
 const all:M73Version[]=[]
 const worksheets:M73Register['worksheets']=[]
 for(const head of data.heads){verify(head.company_id===companyId&&m71Uuid(head.id)&&m71Uuid(head.source_id));const versions:M73Version[]=[]
  for(const row of data.versions.filter(r=>r.worksheet_id===head.id)){
   const v=structuredClone(row.payload) as M73Version,prior=versions[versions.length-1]
   try{m73Keys(v,['id','companyId','worksheetId','version','previousVersionId','previousVersionSha256','createdBy','createdAt','contributorIds','correctionReason','activity','coverageVersion','statement','calculation','findings','inputSha256','contentSha256','versionSha256','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance','review'])}catch{return fail()}
   verify(v.id===row.id&&m71Uuid(v.id)&&v.companyId===companyId&&row.company_id===companyId&&v.worksheetId===head.id&&v.version===versions.length+1&&v.version===row.version&&v.previousVersionId===(prior?.id??null)&&v.previousVersionId===row.previous_version_id&&v.previousVersionSha256===(prior?.versionSha256??null)&&v.createdBy===row.created_by&&m71Uuid(v.createdBy)&&v.createdAt===iso(row.created_at)&&v.createdAt>=(prior?.createdAt??'')&&v.review===null)
   verify(Object.entries(flags).every(([k,x])=>(v as any)[k]===x)&&v.activity.binding.sourceId===head.source_id)
   let normalized:M73SaveInput;try{normalized=validateM73Save({...v.activity,expectedVersionId:v.previousVersionId,expectedVersionSha256:v.previousVersionSha256,correctionReason:v.correctionReason,idempotencyKey:v.id})}catch{return fail()}
   verify(same(m73Activity(normalized),v.activity));if(prior)verify(!same(prior.activity,v.activity)||prior.correctionReason!==v.correctionReason)
   const cv=coverage.versions.find(x=>x.id===v.activity.binding.coverageVersionId);verify(cv&&row.coverage_version_id===cv.id&&same({...cv!,review:null},v.coverageVersion));try{m73ResolveBinding(v.activity.binding,v.coverageVersion)}catch{return fail()}
   const contributors=[...new Set([...(prior?.contributorIds??[]),...v.coverageVersion.contributorIds,v.createdBy])].sort();verify(same(v.contributorIds,contributors)&&same(v.findings,deriveM73Findings(v.activity)))
   if(v.activity.statement===null)verify(v.statement===null&&row.statement_id===null);else{const s=v.statement;verify(s&&row.statement_id===s.id&&m71Uuid(s.id));const matches=data.statements.filter(x=>x.id===s!.id);verify(matches.length===1);const sr=matches[0];let expectedText:string;try{expectedText=m73StatementText(v.activity,v.coverageVersion)}catch{return fail()}
    verify(same(s,{id:s!.id,profile:'m73-synthetic-gas-statement-v1',input:v.activity.statement,locator:`m73-statement:${s!.id}:annual-activity`,text:expectedText,sha256:m73BytesHash(expectedText),byteLength:bytes(expectedText)})&&same(sr.payload,s)&&sr.company_id===companyId&&sr.statement_text===expectedText&&sr.statement_sha256===s!.sha256)
   }
   verify(row.quantity_mmbtu===v.activity.quantityMmbtu)
