    if not v: raise ValueError('invalid M73 calculation contract')
def keys(v,names): require(isinstance(v,dict) and set(v)==set(names.split(',')))
def exact(v):
    t=format(v,'f')
    return t.rstrip('0').rstrip('.') if '.' in t else t
