   const effective={snapshot:draft,expectedVersionId:latest?.id??null,expectedVersionSha256:latest?.versionSha256??null,correctionReason:latest?reason:null};const signature=JSON.stringify({action,...effective});if(pending.current?.signature!==signature)pending.current={signature,key:crypto.randomUUID()}
   await corporateSaveRequest(actor,workspaceId,saved?.inventoryId??null,{...effective,idempotencyKey:pending.current.key})
  }else if(action==="review"&&latest&&saved?.inventoryId){
   const effective={versionId:latest.id,expectedVersionSha256:latest.versionSha256,decision:reviewDecision,note:reviewNote,acknowledgedLimitations:acknowledged?[...M71_LIMITATIONS]:[]};const signature=JSON.stringify({action,...effective});if(pending.current?.signature!==signature)pending.current={signature,key:crypto.randomUUID()}
   await corporateReviewRequest(actor,workspaceId,saved.inventoryId,{...effective,idempotencyKey:pending.current.key})
  }
  const register=await corporateRegisterRequest(actor,workspaceId);if(!active())return;accept(register);pending.current=null;setMessage(action==="save"?"Coverage version saved. Earlier versions and exports stay unchanged; review is still separate.":action==="review"?"Internal decision saved for this exact version. Coverage remains incomplete.":"Saved coverage refreshed.")
 }catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"Could not save coverage. Retry the same action or refresh.")}}finally{lock.current=false;if(active())setBusy(false)}}
 async function exportVersion(version:M71Version){if(!workspaceId||lock.current||!active())return;lock.current=true;setBusy(true);setError(false);try{const text=await corporateExportRequest(actor,workspaceId,version);if(!active())return;const url=URL.createObjectURL(new Blob([text],{type:"application/json"}));const link=document.createElement("a");link.href=url;link.download=`california-coverage-version-${version.version}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setMessage(`Version ${version.version} coverage downloaded. The frozen save snapshot does not include later review decisions.`)}catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"Export unavailable.")}}finally{lock.current=false;if(active())setBusy(false)}}
 function edit(mutator:(next:M71Snapshot)=>void){setDraft(old=>{const next=clone(old);mutator(next);return next})}
 async function attach(kind:"boundary"|"coverage"|"estimate",id:string,checked:boolean){if(!canEdit||lock.current||!active())return;lock.current=true;setBusy(true);try{const ref=checked?await syntheticCoverageReference():null;if(!active())return;edit(next=>{if(kind==="estimate"){const row=next.coverageItems.find(r=>r.id===id);if(row?.estimateBasis)row.estimateBasis.inputEvidenceRefs=ref?[ref]:[]}else{const row=kind==="boundary"?next.boundaryDecisions.find(r=>r.id===id):next.coverageItems.find(r=>r.id===id);if(row)row.evidenceRefs=ref?[ref]:[]}})}catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"Synthetic reference unavailable.")}}finally{lock.current=false;if(active())setBusy(false)}}
 function updateItem(patch:Partial<M71CoverageItem>){if(selected)edit(next=>{const row=next.coverageItems.find(r=>r.id===selected);if(row)Object.assign(row,patch)})}
 function addOperation(event:FormEvent){event.preventDefault();if(!canEdit)return;if(!operation.name.trim()||!operation.facility.trim()){setError(true);setMessage("Enter the operation and facility names.");return}edit(next=>{const entityId=crypto.randomUUID(),facilityId=crypto.randomUUID(),sourceId=crypto.randomUUID(),interval={...next.period};next.entities.push({id:entityId,legalName:operation.name,countryCode:operation.country,regionCode:operation.region||null,...interval,evidenceRefs:[]});next.facilities.push({id:facilityId,entityId,name:operation.facility,countryCode:operation.country,regionCode:operation.region||null,...interval,evidenceRefs:[]});next.sources.push({id:sourceId,entityId,facilityId,name:"Purchased electricity — assess activity",domain:"electricity",...interval,evidenceRefs:[]});next.boundaryDecisions.push({id:crypto.randomUUID(),entityId,disposition:"unassessed",reason:null,...interval,evidenceRefs:[]});next.relationships.push({id:crypto.randomUUID(),parentEntityId:next.entities[0]!.id,childEntityId:entityId,ownershipPercent:null,controlFacts:null,...interval,evidenceRefs:[]});next.coverageItems.push({id:crypto.randomUUID(),domain:"electricity",entityId,sourceId,...interval,disposition:"unassessed",activityDataState:"not_assessed",evidenceState:"missing",methodReadiness:"unsupported",reason:null,evidenceRefs:[],estimateBasis:null,quantity:null,unit:null})});setOperation({name:"",facility:"",country:"US",region:"CA"});setMessage("Operation added to this unsaved draft. Boundary, control and activity assessment remain open.")}
 function addGasSource(event:FormEvent){
