 }
 const reviewAllowed=manager&&latest&&!latest.contributorIds.includes(actor.userId)&&!latest.review&&!editing
 return <section className="worksheet corporate-register">
  <p className="worksheet-eyebrow">California reporting · Private synthetic workspace</p><h1 ref={headingRef} tabIndex={-1}>Corporate coverage register</h1>
