  <div className="worksheet-report-actions"><button type="button" disabled={busy||editing} onClick={()=>void run("refresh")}>Refresh saved register</button>{manager&&latest&&!editing&&<button type="button" disabled={busy||saved.versions.length>=M71_MAX_VERSIONS} onClick={()=>{setDraft(clone(latest.snapshot));setEditing(true);setReason("");setMessage("Editing a new version. Saved history stays unchanged.")}}>Make a correction</button>}{editing&&latest&&<button type="button" disabled={busy} onClick={()=>{setDraft(clone(latest.snapshot));setEditing(false);setReason("");setError(false);setMessage("Unsaved changes discarded.")}}>Cancel correction</button>}</div>
