   {selectedItem&&<article className="worksheet-card worksheet-form"><h2>{domainName(selectedItem.domain)}</h2><p>Method: {words(selectedItem.methodReadiness)} · Emissions unavailable. Linking a reference does not establish sufficient evidence.</p><fieldset disabled={!canEdit}><label>Proposed category decision<select value={selectedItem.disposition} onChange={e=>{const value=e.target.value as M71Disposition;updateItem({disposition:value,estimateBasis:value==="included_estimate"?{methodVersionId:"synthetic-estimate-proposal-v1",assumptions:"",inputEvidenceRefs:[],uncertainty:""}:null})}}>{Object.entries(dispositions).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><label>Screening rationale<textarea value={selectedItem.reason??""} onChange={e=>updateItem({reason:e.target.value||null})}/></label><div className="coverage-grid"><label>Activity data<select value={selectedItem.activityDataState} onChange={e=>updateItem({activityDataState:e.target.value as M71CoverageItem['activityDataState'],quantity:null,unit:null})}>{['not_assessed','missing','partial','entered','estimate_proposed','explicit_zero'].map(v=><option key={v} value={v}>{words(v)}</option>)}</select></label><label>Evidence status<select value={selectedItem.evidenceState} onChange={e=>updateItem({evidenceState:e.target.value as M71CoverageItem['evidenceState']})}>{['not_assessed','missing','partial','linked','conflicting'].map(v=><option key={v} value={v}>{words(v)}</option>)}</select></label></div><label className="worksheet-check"><input type="checkbox" checked={selectedItem.evidenceRefs.length>0} onChange={e=>void attach("coverage",selectedItem.id,e.target.checked)}/>Link supplied fictional screening reference</label>
   {selectedItem.activityDataState==="explicit_zero"&&<div className="coverage-grid"><label>Explicit quantity<input value={selectedItem.quantity??""} onChange={e=>updateItem({quantity:e.target.value||null})}/></label><label>Unit<input value={selectedItem.unit??""} onChange={e=>updateItem({unit:e.target.value||null})}/></label></div>}
