  {panel==="history"&&<><h2>Saved versions</h2>{saved?.versions.length?<><label className="coverage-version">View version<select value={historical?.id??""} onChange={e=>setHistoryId(e.target.value)}>{saved.versions.map(v=><option key={v.id} value={v.id}>Version {v.version} · {v.createdAt.slice(0,10)}</option>)}</select></label>{historical&&<article className="worksheet-card"><h2>Version {historical.version} · {historical.snapshot.companyLabel}</h2><p>{historical.snapshot.entities.length} entities · {historical.snapshot.facilities.length} facilities · {historical.snapshot.coverageItems.filter(c=>c.domain.startsWith('scope3_')).length} Scope 3 categories</p><p>Review: {historical.review?words(historical.review.decision):"Unreviewed"}. {historical.review?.note}</p>{historical.correctionReason&&<p>Correction: {historical.correctionReason}</p>}<button type="button" disabled={busy} onClick={()=>void exportVersion(historical)}>Download version {historical.version} coverage</button><p>The export is frozen at save and excludes subsequent review decisions. Current review is shown separately above.</p><details><summary>Saved boundary and screenings</summary><ul>{historical.snapshot.entities.map(e=><li key={e.id}>{e.legalName} · {e.regionCode} / {e.countryCode}</li>)}</ul><ul>{historical.snapshot.coverageItems.map(c=><li key={c.id}>{domainName(c.domain)}: {dispositions[c.disposition]} · {words(c.evidenceState)}</li>)}</ul></details><details><summary>Version fingerprint</summary><p className="worksheet-fingerprint">{historical.versionSha256}</p></details></article>}</>:<p>No versions saved yet.</p>}
   {reviewAllowed&&<form className="worksheet-card worksheet-form" onSubmit={e=>{e.preventDefault();void run("review")}}><h2>Review current version {latest.version}</h2><fieldset disabled={busy}><label>Internal decision<select value={reviewDecision} onChange={e=>setReviewDecision(e.target.value as typeof reviewDecision)}><option value="accepted_bounded_internal">Accept bounded internal register</option><option value="changes_requested">Request changes</option></select></label><label>Review note<textarea required value={reviewNote} onChange={e=>setReviewNote(e.target.value)}/></label>{<><ul>{limits.map(l=><li key={l}>{l}</li>)}</ul><label className="worksheet-check"><input type="checkbox" required checked={acknowledged} onChange={e=>setAcknowledged(e.target.checked)}/>I acknowledge these limits and have reviewed the unresolved findings.</label></>}<button type="submit">Save internal review</button></fieldset></form>}
   {latest&&latest.contributorIds.includes(actor.userId)&&<p>A manager who has not contributed to this version or its predecessors must perform the internal review.</p>}
  </>}
