const emptyForm=()=>({quantity:"",statement:true,issuer:"Synthetic energy supplier",reference:"SYN-GAS-2025-001",meterLabel:"Synthetic dedicated boiler meter",stated:"1250.125",description:"Fictional annual natural gas consumed at a dedicated stationary boiler meter; no stock, feedstock, shared-meter or loss adjustments.",confirmed:false,discrepancy:"",zero:"",reason:""})
const words=(text:string)=>text.replace(/_/g," ")
function download(text:string,name:string,type:string){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

export function StationaryNaturalGas({actor,workspaceId,headingRef}:{actor:HostedWorkspaceActor;workspaceId:string|null;headingRef:RefObject<HTMLHeadingElement|null>}){
 const [register,setRegister]=useState<M73Register|null>(null),[streamId,setStreamId]=useState(""),[sourceId,setSourceId]=useState(""),[versionId,setVersionId]=useState("")
 const [fieldErrors,setFieldErrors]=useState<Record<string,string>>({})
 const [editing,setEditing]=useState(false),[form,setForm]=useState(emptyForm),[busy,setBusy]=useState(true),[error,setError]=useState(false),[message,setMessage]=useState("Loading stationary sources…")
 const [reviewNote,setReviewNote]=useState(""),[decision,setDecision]=useState<"accepted_bounded_internal"|"changes_requested">("accepted_bounded_internal"),[ack,setAck]=useState(false)
 const reportCleanup=useRef<(()=>void)|null>(null)
 const lifetime=useRef({active:true}),lock=useRef(false),retry=useRef<{signature:string;key:string}|null>(null)
 const manager=actor.role!=="member",stream=register?.worksheets.find(w=>w.worksheetId===streamId),latest=stream?.versions[stream.versions.length-1],selected=stream?.versions.find(v=>v.id===versionId)??latest
 const choice=register?.sources.find(s=>s.binding.sourceId===sourceId)
 const active=()=>lifetime.current.active&&!actor.signal?.aborted
 const accept=useCallback((value:M73Register,preferred="")=>{setRegister(value);const next=value.worksheets.find(w=>w.worksheetId===preferred)??value.worksheets[0];setStreamId(next?.worksheetId??"");setVersionId(next?.headVersionId??"");setSourceId(next?.sourceId??value.sources.find(s=>s.eligible)?.binding.sourceId??"");setEditing(false);setReviewNote("");setAck(false)},[])
 useEffect(()=>{const state={active:true};lifetime.current=state;void(async()=>{try{if(!workspaceId){setMessage("No company workspace is assigned.");return}const value=await gasRegisterRequest(actor,workspaceId);if(state.active&&!actor.signal?.aborted){accept(value,"");setMessage("Select a saved source or create a stationary source draft.")}}catch(e){if(state.active&&!actor.signal?.aborted){setError(true);setMessage(e instanceof Error?e.message:"Stationary sources unavailable.")}}finally{if(state.active&&!actor.signal?.aborted)setBusy(false)}})();return()=>{state.active=false;reportCleanup.current?.();reportCleanup.current=null}},[actor,workspaceId,accept])
 function patch(change:Partial<ReturnType<typeof emptyForm>>){setForm(old=>({...old,...change}));setFieldErrors({});setError(false)}
 function start(version?:M73Version){if(busy||!manager)return;setEditing(true);setError(false);setFieldErrors({});setAck(false);setReviewNote("");if(version){const a=version.activity;setSourceId(a.binding.sourceId);setForm({quantity:a.quantityMmbtu??"",statement:a.statement!==null,issuer:a.statement?.issuer??"",reference:a.statement?.reference??"",meterLabel:a.statement?.meterLabel??"",stated:a.statement?.statedQuantityMmbtu??"",description:a.statement?.description??"",confirmed:false,discrepancy:a.discrepancyReason??"",zero:a.zeroReason??"",reason:""})}else{setStreamId("");setVersionId("");setForm(emptyForm());setSourceId(register?.sources.find(s=>s.eligible&&!register.worksheets.some(w=>w.sourceId===s.binding.sourceId))?.binding.sourceId??"")}setMessage("Editing an unsaved draft. Save to obtain a calculated source subtotal.")}
 async function action(kind:string,work:(key:string)=>Promise<void>,payload:unknown){if(!workspaceId||lock.current||!active())return;lock.current=true;setBusy(true);setError(false);try{const signature=JSON.stringify({kind,payload});if(retry.current?.signature!==signature)retry.current={signature,key:crypto.randomUUID()};await work(retry.current.key);if(active())retry.current=null}catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"This action could not be completed.")}}finally{lock.current=false;if(active())setBusy(false)}}
 async function save(){
  const issues:Record<string,string>={};let quantity:string|null=null,stated:string|null=null
