  if(form.statement){try{stated=m73Quantity(form.stated)}catch{issues.stated="Enter the statement amount in MMBtu with up to 3 decimal places."}}
  if(quantity!==null){if(!form.statement)issues.statement="Numeric activity needs a retained statement.";if(!form.confirmed)issues.confirmed="Confirm the statement and dedicated-meter consumption basis.";if(quantity==="0.000"){if(stated!=="0.000")issues.stated="Zero activity needs a statement that also states zero.";if(!form.zero.trim())issues.zero="Explain the explicit no-consumption basis."}else if(stated!==null&&quantity!==stated&&!form.discrepancy.trim())issues.discrepancy="Explain why the entered and stated quantities differ."}
