export async function decodeGasReport(value:unknown,companyId:string,version?:M73Version):Promise<M73Report>{try{m71Keys(value,['id','companyId','worksheetId','versionId','versionSha256','decisionId','decisionSha256','createdBy','createdAt','rendererVersion','html','htmlSha256','htmlByteLength','snapshotJson','snapshotSha256','reportSha256']);const r=value as unknown as M73Report;if(r.companyId!==companyId||![r.id,r.worksheetId,r.versionId,r.createdBy].every(m71Uuid)||!instant(r.createdAt)||r.rendererVersion!=='m73-source-report-v1'||!m71HashString(r.versionSha256)||!(r.decisionId===null?r.decisionSha256===null:m71Uuid(r.decisionId)&&m71HashString(r.decisionSha256))||typeof r.html!=='string'||r.htmlByteLength!==new TextEncoder().encode(r.html).length||r.htmlByteLength>131072||await coverageSha256(r.html)!==r.htmlSha256||typeof r.snapshotJson!=='string'||await coverageSha256(r.snapshotJson)!==r.snapshotSha256||await hash(m73ReportHashPayload(r))!==r.reportSha256)return fail();if(version&&(r.versionId!==version.id||r.versionSha256!==version.versionSha256||r.worksheetId!==version.worksheetId||r.createdAt<version.createdAt||r.decisionId!==null&&(r.decisionId!==version.review?.id||r.decisionSha256!==version.review.decisionSha256)))return fail();const snapshot=parseM71Json(r.snapshotJson,M73_MAX_RESPONSE_BYTES) as ReturnType<typeof m73ReportSnapshot>;m71Keys(snapshot,['profile','version','review']);const captured=await decodeGasVersion(snapshot.version,companyId);if(snapshot.profile!=='m73-source-report-v1'||captured.review!==null||captured.id!==r.versionId||captured.versionSha256!==r.versionSha256||captured.worksheetId!==r.worksheetId)return fail();if(snapshot.review!==null)await decodeGasReview(snapshot.review,companyId,captured);if((snapshot.review?.id??null)!==r.decisionId||(snapshot.review?.decisionSha256??null)!==r.decisionSha256||m73CanonicalJson(snapshot)!==r.snapshotJson||m73RenderReport(snapshot)!==r.html)return fail();return r}catch{return fail()}}
export async function decodeGasRegister(value:unknown,companyId:string):Promise<M73Register>{try{m71Keys(value,['profile','companyId','coverageHeadVersionId','worksheets','sources','coverageFindings','limitations','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance']);const r=value as unknown as M73Register;if(r.profile!==M73_PROFILE||r.companyId!==companyId||!m71Uuid(companyId)||!invariant(r)||!equal(r.limitations,M73_LIMITATIONS)||!(r.coverageHeadVersionId===null||m71Uuid(r.coverageHeadVersionId))||!Array.isArray(r.worksheets)||r.worksheets.length>M73_MAX_STREAMS||!Array.isArray(r.sources)||!Array.isArray(r.coverageFindings))return fail();const ids=new Set<string>(),sourceIds=new Set<string>();let count=0;for(const w of r.worksheets){m71Keys(w,['profile','companyId','worksheetId','sourceId','headVersionId','versions','reports','findings','limitations','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance']);if(w.profile!==M73_PROFILE||w.companyId!==companyId||!invariant(w)||!equal(w.limitations,M73_LIMITATIONS)||![w.worksheetId,w.sourceId,w.headVersionId].every(m71Uuid)||ids.has(w.worksheetId)||sourceIds.has(w.sourceId)||!Array.isArray(w.versions)||!w.versions.length||!Array.isArray(w.reports)||!Array.isArray(w.findings))return fail();ids.add(w.worksheetId);sourceIds.add(w.sourceId);let prev:M73Version|undefined;for(const raw of w.versions){const v=await decodeGasVersion(raw,companyId,prev);if(v.version!==(prev?.version??0)+1||v.worksheetId!==w.worksheetId||v.activity.binding.sourceId!==w.sourceId)return fail();prev=v;count++}if(w.headVersionId!==prev?.id||w.reports.length>w.versions.length*2)return fail();for(const report of w.reports){const v=w.versions.find(v=>v.id===report.versionId);if(!v)return fail();await decodeGasReport(report,companyId,v)}}if(count>M73_MAX_VERSIONS)return fail();for(const s of r.sources){m71Keys(s,['binding','companyLabel','entityLabel','facilityLabel','sourceLabel','eligible','findings']);m71Keys(s.binding,['coverageVersionId','coverageVersionSha256','entityId','facilityId','sourceId','boundaryDecisionId']);if(typeof s.eligible!=='boolean'||!Array.isArray(s.findings)||!['companyLabel','entityLabel','facilityLabel','sourceLabel'].every(k=>typeof s[k as keyof typeof s]==='string')||!m71Uuid(s.binding.sourceId)||s.binding.coverageVersionId!==r.coverageHeadVersionId||!m71HashString(s.binding.coverageVersionSha256))return fail()}return r}catch{return fail()}}
async function request(actor:HostedWorkspaceActor,companyId:string,suffix:string,payload?:unknown){actor.signal?.throwIfAborted();if(!m71Uuid(companyId)||!actor.accessToken||/[\r\n]/.test(actor.accessToken))return fail();const response=await fetch(`/workspace-api/workspace/${companyId}/stationary-natural-gas${suffix}`,{method:payload===undefined?'GET':'POST',headers:{authorization:`Bearer ${actor.accessToken}`,...(payload===undefined?{}:{'content-type':'application/json'})},body:payload===undefined?undefined:JSON.stringify(payload),signal:actor.signal,cache:'no-store'});actor.signal?.throwIfAborted();if(response.status===401||response.status===403){actor.onUnauthorized?.();throw new Error('Your access changed. Sign in again to continue.')}if(!response.ok)throw new Error(response.status===409?'The source, boundary or review changed, or this statement is already assigned. Refresh and check the source before retrying.':response.status===422?'Check the source boundary, decimal quantity, statement, confirmation and required explanations. Nothing was saved.':'Stationary source data is unavailable. Retry the same action or refresh.');const text=await response.text();actor.signal?.throwIfAborted();if(new TextEncoder().encode(text).length>M73_MAX_RESPONSE_BYTES)return fail();return text}
export async function gasRegisterRequest(a:HostedWorkspaceActor,c:string){return decodeGasRegister(parseM71Json(await request(a,c,''),M73_MAX_RESPONSE_BYTES),c)}
export async function gasSaveRequest(a:HostedWorkspaceActor,c:string,w:string|null,input:M73SaveInput){if(w!==null&&!m71Uuid(w))return fail();return decodeGasVersion(parseM71Json(await request(a,c,w?`/${w}/versions`:'',input),M73_MAX_RESPONSE_BYTES),c)}
export async function gasReviewRequest(a:HostedWorkspaceActor,c:string,w:string,input:M73ReviewInput){if(!m71Uuid(w))return fail();return decodeGasReview(parseM71Json(await request(a,c,`/${w}/reviews`,input),M73_MAX_RESPONSE_BYTES),c)}
export async function gasReportRequest(a:HostedWorkspaceActor,c:string,w:string,input:M73ReportInput){if(!m71Uuid(w))return fail();return decodeGasReport(parseM71Json(await request(a,c,`/${w}/reports`,input),M73_MAX_RESPONSE_BYTES),c)}
export async function gasStatementDownload(a:HostedWorkspaceActor,c:string,w:string,v:M73Version){if(v.companyId!==c||v.worksheetId!==w||!v.statement||!m71Uuid(w))return fail();const text=await request(a,c,`/${w}/statements/${v.statement.id}/download`);if(text!==v.statement.text||await coverageSha256(text)!==v.statement.sha256)return fail();return text}
export async function gasExportRequest(a:HostedWorkspaceActor,c:string,v:M73Version){if(v.companyId!==c||!m71Uuid(v.worksheetId)||!m71Uuid(v.id))return fail();const text=await request(a,c,`/${v.worksheetId}/versions/${v.id}/calculation-export`);await decodeGasVersion(parseM71Json(text,M73_MAX_RESPONSE_BYTES),c);if(text!==m73Export(v))return fail();return text}
export async function gasReportDownload(a:HostedWorkspaceActor,c:string,w:string,r:M73Report){if(r.companyId!==c||r.worksheetId!==w||!m71Uuid(w)||!m71Uuid(r.id))return fail();const text=await request(a,c,`/${w}/reports/${r.id}/download`);if(text!==r.html||await coverageSha256(text)!==r.htmlSha256)return fail();return text}

